// ─── CONFIG ───
// ⚠️ Replace these template IDs with your own from PDF Generator API.
const TEMPLATES = {
  'General Admission': 1615251,
  'VIP':               1615251,
  'Backstage Pass':    1615251
};
const MAX_CAPACITY = 3; // Set your event capacity here

// ─── Count current registrations ───
const registrations = $('Get Current Registrations').all();
const currentCount = registrations.length;
const spotsLeft = MAX_CAPACITY - currentCount;
const isFull = spotsLeft <= 0;

// ─── Form data ───
const form = $('Event Registration Form').item.json;

// ─── Generate unique ticket ID ───
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let suffix = '';
for (let i = 0; i < 8; i++) {
  suffix += chars[Math.floor(Math.random() * chars.length)];
}
const ticketId = 'TKT-' + suffix;

const now = new Date();
const issuedDate = now.toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});
const isoTimestamp = now.toISOString();

const ticketTier = form['Ticket Tier'] || 'General Admission';
const tierBadge = ticketTier === 'VIP' ? 'VIP'
  : ticketTier === 'Backstage Pass' ? 'BACKSTAGE'
  : 'GENERAL';
const tierColor = ticketTier === 'VIP' ? '#7B2FBE'
  : ticketTier === 'Backstage Pass' ? '#C0392B'
  : '#0f3460';

const templateId = TEMPLATES[ticketTier] || TEMPLATES['General Admission'];

return [{
  json: {
    isFull,
    currentCount,
    spotsLeft,
    maxCapacity: MAX_CAPACITY,
    ticketId,
    attendeeName:  form['Full Name'],
    attendeeEmail: form['Email Address'],
    eventName:     form['Event Name'],
    venue:         form['Venue'],
    eventDate:     form['Event Date'],
    seatNumber:    form['Seat Preference'],
    ticketTier,
    tierBadge,
    tierColor,
    templateId,
    issuedDate,
    isoTimestamp,
    outputName: `event-ticket-${ticketId}`,
    templateData: {
      ticket_id:     ticketId,
      attendee_name: form['Full Name'],
      event_name:    form['Event Name'],
      venue:         form['Venue'],
      event_date:    form['Event Date'],
      seat_number:   form['Seat Preference'],
      ticket_tier:   tierBadge,
      issued_date:   issuedDate
    }
  }
}];

const input = $input.item.json;
const ticketId = (input.body && input.body.ticket_id) || input.ticket_id || '';

if (!ticketId || !ticketId.startsWith('TKT-')) {
  throw new Error(`Invalid or missing ticket_id: "${ticketId}". Expected format: TKT-XXXXXXXX`);
}

return [{
  json: {
    ticketId
  }
}];

// ─── CONFIG (must match Flow A) ───
const TEMPLATES = {
  'General Admission': 1615251,
  'VIP':               1615251,
  'Backstage Pass':    1615251
};

// ─── Get first waitlisted person (lowest row number) ───
const waitlist = $input.all().map(i => i.json);
waitlist.sort((a, b) => Number(a.row_number) - Number(b.row_number));
const first = waitlist[0];

// ─── Generate ticket ID for promoted attendee ───
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let suffix = '';
for (let i = 0; i < 8; i++) {
  suffix += chars[Math.floor(Math.random() * chars.length)];
}
const ticketId = 'TKT-' + suffix;

const now = new Date();
const issuedDate = now.toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});
const isoTimestamp = now.toISOString();

// ─── Read actual field names as stored in the Waitlist sheet ───
const ticketTier = first.ticketTier || 'General Admission';
const tierBadge = ticketTier === 'VIP' ? 'VIP'
  : ticketTier === 'Backstage Pass' ? 'BACKSTAGE'
  : 'GENERAL';
const tierColor = ticketTier === 'VIP' ? '#7B2FBE'
  : ticketTier === 'Backstage Pass' ? '#C0392B'
  : '#0f3460';

const templateId = TEMPLATES[ticketTier] || TEMPLATES['General Admission'];

return [{
  json: {
    ticketId,
    attendeeName:     first.attendeeName,
    attendeeEmail:    first.attendeeEmail,
    eventName:        first.eventName,
    venue:            first.venue,
    eventDate:        first.eventDate,
    seatNumber:       first.seatNumber,
    ticketTier,
    tierBadge,
    tierColor,
    templateId,
    issuedDate,
    isoTimestamp,
    waitlistPosition: first.row_number,
    outputName: `event-ticket-promoted-${ticketId}`,
    templateData: {
      ticket_id:     ticketId,
      attendee_name: first.attendeeName,
      event_name:    first.eventName,
      venue:         first.venue,
      event_date:    first.eventDate,
      seat_number:   first.seatNumber,
      ticket_tier:   tierBadge,
      issued_date:   issuedDate
    }
  }
}];
